<script setup lang="ts">
import type { Submission } from '../../shared/types'
const props=defineProps<{submission:Submission}>()
const selected=ref(0)
const current=computed(()=>props.submission.results?.[selected.value])
</script>
<template><div class="submission-result"><div class="result-heading"><VerdictBadge :value="submission.verdict"/><span class="mono">{{submission.score}} 分</span><span>{{submission.passed}} / {{submission.total}} 通过</span><span>{{submission.language==='c'?'C11（历史）':'MIPS32'}}</span></div><a-alert v-if="submission.error" type="error" :message="submission.error" show-icon/><div v-if="submission.results?.length" class="case-grid"><button v-for="(r,i) in submission.results" :key="r.index" :class="['case-chip',{pass:r.verdict==='Accepted',selected:selected===i}]" @click="selected=i"><span>#{{r.index}}</span><small>{{r.verdict==='Accepted'?'AC':r.verdict==='Wrong Answer'?'WA':r.verdict==='Time Limit Exceeded'?'TLE':r.verdict==='Compile Error'?'CE':'RE'}}</small></button></div><template v-if="current"><div class="case-description"><strong>{{current.label}}</strong><span>{{current.time}} ms（含进程启动）</span></div><div class="io-grid"><div><div class="io-label">输入</div><pre>{{current.input}}</pre></div><div><div class="io-label">标准输出</div><pre>{{current.expected}}</pre></div></div><div class="io-label">实际输出</div><pre :class="{'error-output':current.verdict!=='Accepted'}">{{current.actual||'（无输出）'}}</pre><template v-if="current.error"><div class="io-label">错误信息</div><pre class="error-output">{{current.error}}</pre></template></template></div></template>
